import {worlds,missions} from './data.js?v=3';
import {art,crystal,robotScene} from './art.js?v=3';
const $=s=>document.querySelector(s), KEY='secret-game-world-v1';
const blankTask=()=>({selected:[],revealed:[],step:0,slots:[],found:[],memory:'ready',deadline:0,remaining:15000,answers:[],code:'',opened:-1,solved:false,feedback:''});
const fresh=()=>({route:'start',resume:'story',index:0,done:[],skipped:[],crystals:[],sound:false,low:matchMedia('(prefers-reduced-motion: reduce)').matches,adjust:0,story:0,task:blankTask(),started:0,elapsed:0,paused:false,bye:[]});
let saved;try{saved=JSON.parse(localStorage.getItem(KEY));}catch{}
let s=saved?.done&&saved?.task?{...fresh(),...saved,route:'start'}:fresh();
let teacher=false,modal='',hint=false,showAnswer=false;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>missions[s.index];
const xp=()=>Math.max(0,Math.min(330,s.done.length*10+s.adjust));
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(s));}catch{}};
function route(r){if(s.route!=='start')s.resume=s.route;s.route=r;if(r!=='start')s.resume=r;modal='';hint=false;showAnswer=false;save();render();}
function enter(i){s.index=i;s.task=blankTask();hint=false;showAnswer=false;route(i>=28?'boss':'mission');}
function tone(ok){if(!s.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;const ctx=new C();[0,1,2].forEach((n)=>{let o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=(ok?523:220)*[1,1.25,1.5][n];g.gain.setValueAtTime(.045,ctx.currentTime+n*.1);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+n*.1+.18);o.start(ctx.currentTime+n*.1);o.stop(ctx.currentTime+n*.1+.2);});setTimeout(()=>ctx.close(),700);}catch{}}
function complete(){s.task.solved=true;s.task.feedback='Great job!';s.task.awarded=!s.done.includes(current().id);if(s.task.awarded){s.done.push(current().id);s.skipped=s.skipped.filter(x=>x!==current().id);}tone(true);save();render();}
function wrong(){s.task.feedback='Not quite! Try again!';tone(false);save();render();}
function next(skip=false){const m=current();if(!s.task.solved&&!skip)return;if(skip&&!s.done.includes(m.id)&&!s.skipped.includes(m.id))s.skipped.push(m.id);
 if(s.index===32){route('victory');return;}
 if(s.index===worlds[m.world].range[1]-1){if(!s.crystals.includes(m.world))s.crystals.push(m.world);route('reward');return;}enter(s.index+1);
}
const btn=(label,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const options=(m,opts=m.options)=>`<div class="choices ${opts.length>4?'five':''} ${m.visual==='animals'?'picture-choices':''}">${opts.map((o,i)=>{const sel=s.task.selected.includes(i),picture=m.visual==='animals'||(['memory','riddles'].includes(m.type)&&!/^\d+$/.test(o)&&!['blue','yellow','pink','green','red','black'].includes(o));return `<button class="option ${sel?'selected':''} ${m.visual==='colours'?'swatch':''}" data-action="choose" data-i="${i}" ${s.task.solved?'disabled':''} style="${m.visual==='colours'?`--swatch:${colours[o]}`:''}"><span class="letter">${String.fromCharCode(65+i)}</span>${picture?art(o):''}${m.visual==='colours'?`<img class="color-word-art" src="assets/game/colors/${o}.webp" alt="${esc(o.toUpperCase())}" draggable="false">`:`<span>${esc(o.toUpperCase())}</span>`}${sel?'<b class="tick">✓</b>':''}</button>`;}).join('')}</div>`;
const colours={red:'#ff5d79',blue:'#48b0ff',green:'#66d994',yellow:'#ffda5e',pink:'#f993ce',grey:'#adbad0',brown:'#b18a68',orange:'#ffab63',purple:'#b28aef',black:'#39364f'};
function header(){return `<header class="hud"><button class="brand" data-action="home" aria-label="Home"><img src="assets/pix.webp" alt=""><span>THE SECRET<br><b>GAME WORLD</b></span></button><div class="journey"><span>${s.route==='start'?'YOUR ADVENTURE STARTS HERE':s.route==='map'?'THE WORLD MAP':['mission','boss'].includes(s.route)?worlds[current().world].name.toUpperCase():'SAVE THE GAME!'}</span><div class="progress" role="progressbar" aria-label="Mission progress" aria-valuenow="${s.done.length+s.skipped.length}" aria-valuemin="0" aria-valuemax="33"><i style="width:${(s.done.length+s.skipped.length)/33*100}%"></i></div></div><div class="crystal-slots">${[0,1,2].map(i=>`<div class="crystal-slot ${s.crystals.includes(i)?'earned':''}" title="${worlds[i].short}">${crystal(i,true)}</div>`).join('')}</div><div class="xp"><img class="xp-art" src="assets/game/ui/xp_badge.webp" alt=""> ${xp()} <small>XP</small></div></header>`;}
function footer(){return `<footer><div class="footer-left"><span class="live-dot"></span><span>ENGLISH A1</span><i></i><span>PLAY TOGETHER. WIN TOGETHER.</span></div><nav aria-label="Game controls">${btn('⌂ <span>HOME</span>','home')}${btn('♧ <span>MAP</span>','map')}${btn(`${s.sound?'♫':'♪'} <span>SOUND ${s.sound?'ON':'OFF'}</span>`,'sound','',`aria-pressed="${s.sound}"`)}${btn('⛶ <span>FULL SCREEN</span>','fullscreen')}${btn('⚿ <span>TEACHER</span>','teacher',teacher?'active':'')}</nav></footer>`;}
function start(){return `<section class="start scene" style="--bg:url('assets/map.webp')"><div class="start-copy"><span class="eyebrow">AN ENGLISH ADVENTURE FOR YOUR WHOLE CLASS</span><h1><span>THE SECRET</span><br>GAME WORLD</h1><p class="tagline">Three crystals. One big adventure.<br>Can you save the game?</p><div class="hero-crystals">${[0,1,2].map(i=>crystal(i)).join('')}</div><div class="start-actions">${btn('Начать путешествие <span>➜</span>','start','primary')}</div><div class="start-meta"><span>3 WORLDS</span><b>·</b><span>33 MISSIONS</span><b>·</b><span>50 MINUTES</span></div></div><div class="hero-art"><div class="portal-ring"></div><img class="hero-pix" src="assets/pix.webp" alt="PIX, your friendly robot guide"><div class="speech">Ready, players?<span>Let’s do this together!</span></div><span class="pix-name">MEET PIX · YOUR GUIDE</span></div><div class="scene-bottom">COLOURS <span>✦</span> NUMBERS <span>✦</span> ANIMALS</div></section>`;}
function story(){const lines=['Oh no! Glitch King has broken our game!','Colours, numbers and animals are disappearing.','Find 3 crystals. Help me save the game!'];return `<section class="story scene" style="--bg:url('assets/map.webp')"><div class="story-character"><img src="assets/${s.story===0?'king':'pix'}.webp" alt="${s.story===0?'Glitch King':'PIX'}"></div><div class="story-card"><span class="eyebrow">THE ADVENTURE · ${s.story+1} / 3</span><h1>${['We need your help!','Our world needs you!','Can you help me?'][s.story]}</h1><p>${lines[s.story]}</p><div class="hero-crystals">${[0,1,2].map(i=>crystal(i,true)).join('')}</div>${btn(s.story===2?'YES, WE CAN! ➜':'NEXT ➜','story-next','primary')}</div></section>`;}
function mapView(){return `<section class="map scene" style="--bg:url('assets/map.webp')"><div class="map-title"><span class="eyebrow">YOUR QUEST</span><h1>Choose your next world</h1><p>Find 3 crystals. Unlock the castle. Save the game!</p></div><div class="map-portals">${worlds.map((w,i)=>{const unlocked=i===0||s.crystals.includes(i-1),done=s.crystals.includes(i);return `<button class="world-node node-${i} ${!unlocked?'locked':''} ${done?'world-done':''}" data-action="world" data-i="${i}" ${!unlocked?'disabled':''}><span class="world-medallion">${i<3?crystal(i):'<img src="assets/king.webp" alt="">'}<b>${done?'✓':unlocked?'➜':'⚿'}</b></span><span class="world-label"><small>${i<3?`WORLD 0${i+1}`:'FINAL BOSS'}</small><strong>${w.name}</strong><em>${done?'CRYSTAL FOUND':unlocked?'ENTER WORLD':'LOCKED'}</em></span></button>`;}).join('')}</div><div class="map-tip"><img src="assets/pix.webp" alt="PIX"><p>${s.crystals.length===3?'All three crystals! Let’s open the castle!':'Together, we can bring our world back!'}</p></div></section>`;}
function counting(type){if(type==='stars')return `<div class="count-stars">${Array.from({length:20},(_,i)=>`<button class="count-object" data-action="count" aria-label="Star ${i+1}">${art('star_coin')}</button>`).join('')}</div>`;
const groups=type==='countRobots'?[['robot',7],['robot',8]]:[['cat',4],['dog',6]];return `<div class="count-groups">${groups.map(([a,n],g)=>`<div class="count-group ${g?'orange-robots':''}">${Array.from({length:n},(_,i)=>`<button class="count-object" data-action="count" aria-label="${a} ${i+1}">${art(type==='countRobots'?`${g?'orange':'blue'}_robot_${i%5+1}`:a)}</button>`).join('')}</div>`).join('<b class="plus">+</b>')}</div>`;}
function memory(m){let t=s.task;if(t.memory==='ready')return `<div class="memory-ready"><div class="memory-icon">◷</div><h2>Look. Remember. Answer!</h2><p>You have 15 seconds.</p>${btn('SHOW FOR 15 SECONDS','memory','primary')}</div>`;
if(t.memory==='look')return `<div class="memory-clock">LOOK! <b id="memory-time">${Math.ceil((t.deadline?Math.max(0,t.deadline-Date.now()):t.remaining)/1000)}</b> seconds</div><div class="memory-grid ${m.id==='C05'?'colour-memory-grid':''}" style="--cols:${m.layout}">${m.options.map(o=>`<div class="memory-item asset-memory-card"><div class="memory-object">${/^\d+$/.test(o)?`<b>${o}</b>`:art(o)}</div></div>`).join('')}</div>`;
const q=m.questions[t.step];return `<div class="mini-step">REMEMBER · ${t.step+1} / ${m.questions.length}</div><h2 class="subprompt">${esc(q.prompt)}</h2>${options({...m,visual:m.id==='A10'?'animals':''},q.options)}`;}
function reveal(m){const sequence=m.type==='sequenceReveal',items=sequence?[m.options[s.task.step]]:m.options;return `<div class="reveal-board">${items.map((o,j)=>{let i=sequence?s.task.step:j;return `<button class="reveal-card ${s.task.revealed.includes(i)?'revealed':''}" data-action="reveal" data-i="${i}">${art(o)}<span>${esc(o.toUpperCase())}${m.id!=='C07'?' is…':''}</span><b>${s.task.revealed.includes(i)?esc(m.correctAnswer[i]):'REVEAL'}</b></button>`;}).join('')}</div>${sequence&&s.task.step<2&&s.task.revealed.includes(s.task.step)?btn('NEXT OBJECT ➜','reveal-next','secondary'):''}`;}
function boxes(m){return `<div class="boxes">${m.options.map((o,i)=>{let opened=s.task.opened===i;return `<button class="mystery ${opened?'opened':''}" data-action="box" data-i="${i}" ${s.task.solved?'disabled':''}><div class="box-clue ${m.visual==='silhouettes'&&!opened?'silhouette':''}">${/^\d+$/.test(o)?`<b>${o}</b>`:art(o)}</div><div class="chest asset-chest"><img src="assets/game/props/mystery_box_gift.webp" alt="Closed mystery box"></div>${opened?`<div class="box-reveal" style="color:${colours[m.reveals[i]]||'#ddc9ff'}">${esc(m.reveals[i].toUpperCase())}</div>`:''}</button>`;}).join('')}</div>`;}
function sorting(m){let match=m.type==='match';return `<div class="sort-board"><div class="sort-source">${m.options.map((o,i)=>`<button class="sort-item ${s.task.selected[0]===i?'selected':''} ${s.task.slots.includes(o)?'placed':''}" draggable="true" data-drag="${i}" data-action="pick" data-i="${i}" ${s.task.solved?'disabled':''}>${match?art(o):''}<b>${esc(o.toUpperCase())}</b></button>`).join('')}</div><p class="sort-instruction">Choose an item, then choose a space. You can drag it, too!</p><div class="sort-slots">${(match?m.targets:m.options).map((o,i)=>`<button class="sort-slot ${s.task.slots[i]?'filled':''}" data-drop="${i}" data-action="place" data-i="${i}" ${s.task.solved?'disabled':''}>${match?`<div class="home-art">${art(o)}<b>${o.toUpperCase()}</b></div>`:''}<span>${s.task.slots[i]?(match?art(s.task.slots[i]):`<b>${esc(s.task.slots[i])}</b>`):'＋'}</span>${match&&s.task.solved?'<em>✓</em>':''}</button>`).join(match?'':'<b class="less">&lt;</b>')}</div></div>${!s.task.solved?btn('CHECK','check','primary',s.task.slots.filter(Boolean).length!==4?'disabled':''):''}`;}
function difference(m){if(m.puzzle){return `<div class="difference-count">${s.task.found.length} / 3 FOUND</div><div class="asset-difference" data-action="miss-diff"><img src="assets/game/puzzles/${m.puzzle}.webp" alt="Pictures A and B. Find three differences." draggable="false">${m.hotspots.map((zone,i)=>`<button class="asset-diff-zone ${s.task.found.includes(m.correctAnswer[i])?'found':''}" style="left:${zone[0]}%;top:${zone[1]}%;width:${zone[2]}%;height:${zone[3]}%" data-action="diff" data-i="${i}" aria-label="${m.zoneLabels[i]}">${s.task.found.includes(m.correctAnswer[i])?'✓':''}</button>`).join('')}</div>`;}let robot=m.visual==='robots';return `<div class="difference-count">${s.task.found.length} / 3 FOUND</div><div class="difference-board">${[0,1].map(side=>`<div class="difference-picture ${robot?'robot-picture':'jungle-picture'}" data-action="miss-diff"><span class="picture-label">${side?'B':'A'}</span>${robot?robotScene(!!side):`<div class="jungle-bg">${art('jungle')}</div><div class="bird ${side?'blue-bird':'red-bird'}">${art('parrot')}</div><div class="tree-monkey">${side?'':art('monkey')}</div><div class="bananas">${Array.from({length:side?2:3},()=>art('banana')).join('')}</div>`}${m.correctAnswer.map((z,i)=>`<button class="diff-zone ${robot?'robot-zone':'jungle-zone'} zone-${i} ${s.task.found.includes(z)?'found':''}" data-action="diff" data-i="${i}" aria-label="${robot?['Antenna','Boot','Back panel'][i]:['Bird','Tree','Bananas'][i]} in picture ${side?'B':'A'}">${s.task.found.includes(z)?'✓':''}</button>`).join('')}</div>`).join('')}</div>`;}
function keypad(m){let math=m.type==='math',step=s.task.step;return `<div class="lock-board">${math?`<div class="math-question">${m.options[step]} = ?</div><div class="math-progress">${m.options.map((o,i)=>`<span class="${i===step?'current':''}">${o}<b>${i===step?s.task.code||'…':s.task.answers[i]||'…'}</b></span>`).join('')}</div>`:`<div class="shape-groups">${[['heart',3],['diamond',2],['star',4]].map(([a,n])=>`<div class="shape-group ${a}">${Array.from({length:n},()=>art(a)).join('')}</div>`).join('')}</div><div class="code-order"><span>RED</span> → <span>BLUE</span> → <span>GREEN</span></div>`}<div class="code-display" aria-live="polite">${math?`<span>${s.task.code||'–'}</span>`:Array.from({length:3},(_,i)=>`<span>${s.task.code[i]||'–'}</span>`).join('')}</div><div class="keypad">${['1','2','3','4','5','6','7','8','9','CLEAR','0','⌫'].map(n=>btn(n,'key','',`data-value="${n}" ${s.task.solved?'disabled':''}`)).join('')}</div>${!s.task.solved?btn(math?(step===2?'UNLOCK':'NEXT NUMBER ➜'):'UNLOCK','unlock','primary',!s.task.code||(!math&&s.task.code.length!==3)?'disabled':''):''}</div>`;}
function taskBody(m){switch(m.type){case 'memory':return memory(m);case 'reveal':case 'sequenceReveal':return reveal(m);case 'box':return boxes(m);case 'sort':case 'match':return sorting(m);case 'difference':return difference(m);case 'math':case 'code':return keypad(m);case 'riddles':return `<div class="mini-step">RIDDLE ${s.task.step+1} / 3</div><p class="riddle">${m.questions[s.task.step]}</p>${options(m)}`;default:return `${['stars','countRobots','countAnimals'].includes(m.visual)?counting(m.visual):m.visual==='silhouette'?`<div class="silhouette-target ${s.task.solved?'':'silhouette'}">${art('giraffe')}</div>`:m.visual==='missing'?`<div class="missing-grid">${['cow','tiger','?','dog','elephant','parrot'].map(o=>`<div>${o==='?'?(s.task.solved?art('dolphin'):'<b>?</b>'):art(o)}</div>`).join('')}</div>`:m.visual&&!['colours','animals'].includes(m.visual)?`<div class="number-road">${esc(m.visual)}</div>`:''}${options(m)}${m.type==='multi'&&!s.task.solved?btn('CHECK','check','primary',!s.task.selected.length?'disabled':''):''}`;}}
function mission(){const m=current(),w=worlds[m.world],index=s.index-w.range[0]+1;return `<section class="mission scene world-${m.world}" style="--bg:url('assets/${w.asset}.webp');--accent:${w.color}"><div class="mission-topline"><span class="world-chip">${m.world===3?'BOSS LOCK':w.short} ${index} / ${w.range[1]-w.range[0]}</span><div class="mission-dots">${Array.from({length:w.range[1]-w.range[0]},(_,i)=>`<i class="${i<index-1?'done':i===index-1?'now':''}"></i>`).join('')}</div>${btn('<img src="assets/game/ui/question_badge.webp" alt=""> HINT','hint','hint-button')}</div><h1>${m.title}</h1><p class="student-prompt">${m.studentPrompt}</p><div class="task-area ${m.type} ${m.type==='choice'&&m.visual==='colours'?'colour-scanner':''}">${taskBody(m)}</div><div class="task-status ${s.task.solved?'success':s.task.feedback?'retry':''}" role="status">${s.task.solved?`<span>✓ ${s.task.feedback} <b>${s.task.awarded?'+10 XP':'XP ALREADY EARNED'}</b></span>${m.spokenAnswer?`<small>Say: “${m.spokenAnswer}”</small>`:''}${btn('NEXT ➜','next','primary')}`:s.task.feedback?`<span>${s.task.feedback}</span>`:'<span>LOOK · THINK · SAY IT TOGETHER!</span>'}</div></section>`;}
function reward(){const i=current().world;return `<section class="reward scene" style="--bg:url('assets/${worlds[i].asset}.webp')"><span class="eyebrow">WORLD ${i+1} COMPLETE</span><h1>${['Rainbow','Number','Animal'][i]} Crystal unlocked!</h1><div class="reward-crystal">${crystal(i)}</div><p>Great teamwork, players!</p><div class="reward-slots">${[0,1,2].map(j=>`<div class="${s.crystals.includes(j)?'earned':''}">${crystal(j,true)}</div>`).join('')}</div><p>${s.crystals.length} OF 3 CRYSTALS FOUND</p>${btn('WORLD MAP ➜','map','primary')}</section>`;}
function victory(){return `<section class="victory scene" style="--bg:url('assets/castle.webp')"><span class="eyebrow">THE GAME WORLD IS SAVED!</span><h1>YOU DID IT!</h1><p class="victory-sub">You are English heroes!</p><div class="victory-art"><img src="assets/pix.webp" alt="Happy PIX"><div class="victory-crystals">${[0,1,2].map(i=>`<div>${crystal(i)}<span>${worlds[i].short} ✓</span></div>`).join('')}</div></div><p>You saved the Game World! English heroes win together!</p><div class="final-xp">✦ ${xp()} <small>/ 330 XP</small></div><div class="victory-buttons">${btn('ONE LAST CHALLENGE ➜','goodbye','primary')}${btn('WORLD MAP','map','secondary')}${btn('PLAY AGAIN','new','secondary')}</div></section>`;}
function goodbye(){return `<section class="goodbye scene" style="--bg:url('assets/animals.webp')"><span class="eyebrow">BEFORE YOU GO… SAY:</span><h1>${s.bye.length===3?'GAME COMPLETE!':'One more time, heroes!'}</h1><div class="goodbye-challenges">${['Five colours!','Count from 20 to 30!','Name three sea animals!'].map((v,i)=>`<button class="${s.bye.includes(i)?'checked':''}" data-action="bye-check" data-i="${i}">${i===0?crystal(0):art(i===1?'robot':'dolphin')}<strong>${v}</strong><span>${s.bye.includes(i)?'✓':'DONE?'}</span></button>`).join('')}</div><p>${s.bye.length===3?'Thank you, players! We did it together!':'Say it together. Then choose DONE!'}</p>${btn('WORLD MAP','map','primary')}${btn('PLAY AGAIN','new','secondary')}</section>`;}
function teacherPanel(){const m=current(),active=['mission','boss'].includes(s.route);return `<aside class="teacher-panel"><div class="teacher-title"><span>⚿ Режим учителя</span>${btn('×','teacher','','aria-label="Закрыть режим учителя"')}</div><p>План урока: 50:00<br><b id="lesson-time">${lessonTime()}</b> · ${s.paused?'пауза':'прошло'}</p><div class="schedule">${[['Вступление','00:00–03:00'],...worlds.map(w=>[w.name,w.time]),['Финал','48:00–50:00 · 2 мин']].map(([a,b])=>`<div><span>${a}</span><small>${b}</small></div>`).join('')}</div>${active?`<h3>${m.id} · ${esc(m.title)}</h3><p>Ориентир: ${m.durationSeconds} сек.<br>Look! Think! Say it together!</p><div class="teacher-buttons">${btn('SHOW HINT','hint')}${btn('SHOW ANSWER','answer')}${btn('RESET TASK','reset')}${btn('SKIP TASK','skip','',m.id==='B05'?'disabled':'')}${btn('BACK','back','',s.index===0?'disabled':'')}${btn('NEXT','teacher-next')}</div>${m.type==='memory'?`<div class="teacher-buttons">${btn(s.task.deadline?'PAUSE MEMORY TIMER':'RESUME MEMORY TIMER','pause-memory','',s.task.memory!=='look'?'disabled':'')}${btn('REPLAY MEMORY','memory')}</div>`:''}${showAnswer?`<div class="teacher-answer"><b>Ответ</b><p>${answerText(m)}</p></div>`:''}`:''}<div class="teacher-buttons">${btn(s.paused?'RESUME LESSON TIMER':'PAUSE LESSON TIMER','pause-lesson')}${btn(s.sound?'SOUND ON':'NO SOUND','sound')}${btn(`${s.low?'✓ ':''}LOW MOTION`,'motion')}</div><label class="xp-editor">Ручная корректировка XP<input type="number" id="xp-adjust" min="0" max="330" step="10" value="${xp()}" aria-label="Общее количество XP"></label><p>Кристаллы: ${s.crystals.length} / 3<br>Завершено: ${s.done.length} / 33<br>Пропущено: ${s.skipped.length}</p>${btn('WORLD MAP','map','secondary')}${btn('NEW GAME','new','secondary')}</aside>`;}
function answerText(m){if(m.byIndex)return esc(m.reveals?.[m.correctAnswer]||m.options[m.correctAnswer]);if(m.type==='difference')return esc(m.hint);if(m.type==='match')return m.options.map((o,i)=>`${o} → ${m.correctAnswer[i]}`).join('; ');return esc(Array.isArray(m.correctAnswer)?m.correctAnswer.join('; '):m.correctAnswer);}
function lessonTime(){const seconds=Math.floor((s.elapsed+(s.started&&!s.paused?Date.now()-s.started:0))/1000);return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function render(){document.body.classList.toggle('low-motion',s.low);document.body.classList.toggle('teacher-open',teacher);$('#app').innerHTML=`${header()}<main>${({start,story,map:mapView,mission,boss:mission,reward,victory,goodbye}[s.route]||start)()}</main>${footer()}${teacher?teacherPanel():''}${hint?`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="Hint"><span class="eyebrow">PIX HAS A HINT</span><img src="assets/pix.webp" alt="PIX"><h2>${esc(current().hint)}</h2>${btn('GOT IT!','close','primary')}</section></div>`:''}${modal==='new'?`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><h2>Start a new adventure?</h2><p>Your saved progress will be reset.</p>${btn('NEW GAME','confirm-new','primary')}${btn('GO BACK','close','secondary')}</section></div>`:''}`;if(hint||modal)document.querySelector('.modal button')?.focus();}
function startNew(){s=fresh();s.started=Date.now();saved=null;teacher=false;route('story');}
function choose(i){const m=current(),t=s.task;if(t.solved)return;if(m.type==='multi'){t.selected=t.selected.includes(i)?t.selected.filter(x=>x!==i):[...t.selected,i];t.feedback='';save();render();return;}
let expected=m.correctAnswer,value=m.options[i];if(m.type==='memory'){if(t.memory!=='recall')return;let q=m.questions[t.step];expected=q.answer;value=q.options[i];}else if(m.type==='riddles'){expected=m.correctAnswer[t.step];}else if(m.byIndex)value=i;
if(value===expected){if(m.type==='memory'||m.type==='riddles'){const n=m.questions.length;if(t.step<n-1){t.step++;t.feedback='Great! Keep going!';tone(true);save();render();return;}}t.selected=[i];complete();}else{t.selected=[];wrong();}}
function check(){const m=current(),t=s.task;if(t.solved)return;let ok=false;if(m.type==='multi'){const picked=t.selected.map(i=>m.options[i]);ok=picked.length===m.correctAnswer.length&&m.correctAnswer.every(o=>picked.includes(o));}else if(m.type==='sort')ok=m.correctAnswer.every((o,i)=>o===t.slots[i]);else if(m.type==='match')ok=m.targets.every((target,i)=>m.correctAnswer[m.options.indexOf(t.slots[i])]===target);ok?complete():wrong();}
function place(i){let t=s.task,m=current();if(t.solved)return;if(t.selected.length){let item=m.options[t.selected[0]],prev=t.slots.indexOf(item);if(prev>=0)t.slots[prev]=null;t.slots[i]=item;t.selected=[];}else{t.slots[i]=null;}t.feedback='';save();render();}
function key(v){if(s.task.solved)return;const len=current().type==='code'?3:2;if(v==='CLEAR')s.task.code='';else if(v==='⌫'||v==='Backspace')s.task.code=s.task.code.slice(0,-1);else if(/^\d$/.test(v)&&s.task.code.length<len)s.task.code+=v;s.task.feedback='';save();render();}
function unlock(){const m=current(),t=s.task;if(t.solved)return;if(m.type==='code'){if(t.code===m.correctAnswer)complete();else wrong();}else{t.answers[t.step]=t.code;if(t.step<2){t.step++;t.code=t.answers[t.step]||'';t.feedback='';save();render();}else if(m.correctAnswer.every((v,i)=>v===t.answers[i]))complete();else{t.step=0;t.code=t.answers[0]||'';wrong();}}}
document.addEventListener('click',async e=>{let el=e.target.closest('[data-action]');if(!el||el.disabled)return;let a=el.dataset.action,i=Number(el.dataset.i),t=s.task,m=current();switch(a){
 case 'start':if(s.started||s.done.length){route(s.resume==='start'?'story':s.resume);}else startNew();break;
 case 'continue':s.route=s.resume==='start'?'story':s.resume;if(!s.started&&!s.paused)s.started=Date.now();save();render();break;
 case 'new':modal='new';render();break;case 'confirm-new':startNew();break;case 'close':hint=false;modal='';render();break;
 case 'story-next':if(s.story<2){s.story++;save();render();}else route('map');break;
 case 'home':route('start');break;case 'map':route('map');break;
 case 'world':if(i===0||s.crystals.includes(i-1)){const [from,to]=worlds[i].range;let n=missions.findIndex((q,j)=>j>=from&&j<to&&!s.done.includes(q.id)&&!s.skipped.includes(q.id));if(current().world===i&&!t.solved&&!s.skipped.includes(current().id)){route(i===3?'boss':'mission');}else enter(n<0?from:n);}break;
 case 'sound':s.sound=!s.sound;tone(true);save();render();break;
 case 'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{}break;
 case 'teacher':teacher=!teacher;render();break;case 'hint':hint=true;render();break;case 'answer':showAnswer=!showAnswer;render();break;
 case 'motion':s.low=!s.low;save();render();break;
 case 'reset':s.task=blankTask();hint=false;showAnswer=false;save();render();break;
 case 'next':next();break;case 'skip':if(m.id!=='B05')next(true);break;case 'teacher-next':if(m.id!=='B05'||t.solved)next(true);break;
 case 'back':if(s.index>0)enter(s.index-1);break;
 case 'choose':choose(i);break;case 'check':check();break;
 case 'reveal':if(t.solved)break;if(!t.revealed.includes(i))t.revealed.push(i);if(t.revealed.length===m.options.length)complete();else{save();render();}break;
 case 'reveal-next':t.step++;save();render();break;
 case 'box':if(t.solved)break;t.opened=i;if(i===m.correctAnswer)complete();else wrong();break;
 case 'pick':if(!t.solved){t.selected=[i];save();render();}break;case 'place':place(i);break;
 case 'count':el.classList.toggle('counted');el.setAttribute('aria-pressed',el.classList.contains('counted'));break;
 case 'diff':if(t.solved)break;let z=m.correctAnswer[i];if(!t.found.includes(z))t.found.push(z);if(t.found.length===3)complete();else{t.feedback='Great! Find more!';save();render();}break;
 case 'miss-diff':if(!t.solved)wrong();break;
 case 'memory':t.memory='look';t.deadline=Date.now()+15000;t.remaining=15000;t.step=0;t.selected=[];t.solved=false;t.feedback='';save();render();break;
 case 'pause-memory':if(t.memory!=='look')break;if(t.deadline){t.remaining=Math.max(0,t.deadline-Date.now());t.deadline=0;}else t.deadline=Date.now()+t.remaining;save();render();break;
 case 'key':key(el.dataset.value);break;case 'unlock':unlock();break;
 case 'pause-lesson':if(s.paused){s.started=Date.now();s.paused=false;}else{s.elapsed+=s.started?Date.now()-s.started:0;s.started=0;s.paused=true;}save();render();break;
 case 'goodbye':route('goodbye');break;case 'bye-check':s.bye=s.bye.includes(i)?s.bye.filter(j=>j!==i):[...s.bye,i];save();render();break;
 }});
document.addEventListener('dragstart',e=>{let el=e.target.closest('[data-drag]');if(el&&!s.task.solved){s.task.selected=[Number(el.dataset.drag)];e.dataTransfer.setData('text/plain',el.dataset.drag);e.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop]'))e.preventDefault();});
document.addEventListener('drop',e=>{const el=e.target.closest('[data-drop]');if(el){e.preventDefault();place(Number(el.dataset.drop));}});
document.addEventListener('change',e=>{if(e.target.id==='xp-adjust'){const target=Math.min(330,Math.max(0,Number(e.target.value)||0));s.adjust=target-s.done.length*10;save();render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(hint||modal)){hint=false;modal='';render();return;}if(['mission','boss'].includes(s.route)&&['code','math'].includes(current().type)&&!e.target.matches('input')&&!hint&&!modal){if(/^\d$/.test(e.key)||e.key==='Backspace'){e.preventDefault();key(e.key);}else if(e.key==='Enter'&&!e.target.closest('button')&&s.task.code){e.preventDefault();unlock();}}});
setInterval(()=>{const t=s.task;if(['mission','boss'].includes(s.route)&&current().type==='memory'&&t.memory==='look'&&t.deadline){const left=Math.max(0,t.deadline-Date.now());if(left===0){t.memory='recall';t.deadline=0;t.remaining=0;save();render();}else if($('#memory-time'))$('#memory-time').textContent=Math.ceil(left/1000);}if($('#lesson-time'))$('#lesson-time').textContent=lessonTime();},100);
render();
